function PVPArenaPlayerMatcherInfoDialog:__init()
end

function PVPArenaPlayerMatcherInfoDialog:__delete()
    self.info = nil
end

function PVPArenaPlayerMatcherInfoDialog:Awake()
    local parameters = self.controller.Argument.parameters
    self.playerId    = parameters.playerId
    self.info    = parameters.info

    self.listenerConf = {
        [Constants.EventNames.PVPArenaRequestMatcherSuccess] = Bind(self, self.OnRequestMatcherSuccessAction),
        [Constants.EventNames.PVPArenaRequestSeasonRankSuccess] = Bind(self, self.OnRequestSeasonRankSuccessAction),
    }
    for listenerKey, func in pairs(self.listenerConf) do
        Events.AddListener(listenerKey, func)
    end

    UIEventProxy.Create(self.BtnCloseArea.gameObject).onPointerClick = Bind(self, self.OnClickBtnCloseAreaAction)
end

function PVPArenaPlayerMatcherInfoDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            PVPArenaUtils.RefreshCommonUITitleNode(self.CommonUITitleNode.gameObject, localize("玩家信息"))

            self:RefreshBaseUI()

            ---@type PVPArenaDojo
            local pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
            local preSeasonId       = checkNumber(pvpArenaDojo.seasonId) - 1
            self.preSeasonId        = preSeasonId
            pvpArenaComponent:RequestMatcher(self.playerId)
            pvpArenaComponent:RequestSeasonRank(preSeasonId)
        end)

    end))
    return coWait
end

function PVPArenaPlayerMatcherInfoDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        for listenerKey, func in pairs(self.listenerConf) do
            Events.RemoveListener(listenerKey, func)
            func = nil
        end
        self.listenerConf = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

