function PVPArenaPlayerMatcherInfoDialog:RefreshBaseUI()
    local playerId          = self.playerId
    local info              = self.info
    if info == nil then
        local pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
        local matcherInfo       = checkTable(pvpArenaDojo.matcherInfo)
        info              = matcherInfo[tostring(playerId)]
    end

    self.TxtLV.text         = info.level
    self.TextName.text      = info.name
    local excludeDialogs = {}
    PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, playerId, info, excludeDialogs, nil, true)
end


---OnRequestSeasonRankSuccessAction
---请求成功赛季排行
function PVPArenaPlayerMatcherInfoDialog:OnRequestSeasonRankSuccessAction(seasonId, seasonRank)
    if self.preSeasonId ~= seasonId then return end
    local rank = PVPArenaUtils.GetRankBySeasonRank(seasonRank, self.playerId)
    local isOwnRank = rank ~= nil
    KTool.SetActive(self.HighestGroup.gameObject, isOwnRank)
    if isOwnRank then
        PVPArenaUtils.RefreshPVPRankFlagNode(self.PVPRankFlagNode.gameObject, rank)
    end
end

---OnRequestMatcherSuccessAction
---@param data table 参赛者信息
---@param playerId number 玩家id
function PVPArenaPlayerMatcherInfoDialog:OnRequestMatcherSuccessAction(data, playerId)
    if playerId ~= self.playerId then return end

    local rankList = data.rank
    self:RefreshRankingGroups(rankList)
end

---RefreshRankingGroups
---刷新参赛历史
function PVPArenaPlayerMatcherInfoDialog:RefreshRankingGroups(rankList)
    --- 排行 -> 排行个数
    local rank2count = {}
    for i, rankData in ipairs(rankList) do
        local rank = checkNumber(rankData.rank)
        rank2count[rank] = checkNumber(rankData.num)
    end

    ---------------------------
    --- init rank index
    local number = pvpArenaComponent:GetNumberOfContestants()
    --- 写前4
    local t = {1, 2, 3, 4}
    local num = t[4]
    while num < number do
        num = num * 2
        table.insert(t, num)
    end

    ---------------------------
    --- 更新 RankingGroups
    local RankingGroups = self.RankingGroups
    for index, rank in ipairs(t) do
        local rankCount = rank2count[rank] or 0
        local child = RankingGroups:GetChild(index - 1)
        local TextTrans = child:Find("Imgbg/Text")
        if TextTrans then
            CfUtils.FillText(TextTrans.gameObject, string.format("X%s", rankCount))
        end
    end

end

